/**
 * U01 independent tests: flow reducer invariants.
 * Instead of hand-picked sequences (see flow.test.ts), every state reachable from initialFlow within a depth
 * bound is generated by breadth-first search, and every action is applied to every state.
 */
import { describe, expect, it } from 'vitest';
import {
  TAB_ROOT,
  canGoBack,
  flowReducer,
  initialFlow,
  isRoot,
  knownJobs,
  tabOf,
  unfinishedJobs,
  type FlowAction,
  type FlowState,
  type Screen,
  type Tab,
} from './flow.ts';

const TABS: Tab[] = ['trips', 'new', 'feed'];

/** One concrete instance of every action type (two trips so a mismatching id can be tried). */
const ACTIONS: FlowAction[] = [
  { type: 'selectTab', tab: 'trips' },
  { type: 'selectTab', tab: 'new' },
  { type: 'selectTab', tab: 'feed' },
  { type: 'generationStarted', jobId: 'j1', pollAfterMs: 700 },
  { type: 'generationStarted', jobId: 'j2', pollAfterMs: 700 },
  { type: 'generationSucceeded', batchId: 'b1' },
  { type: 'generationEnded', jobId: 'j1' },
  { type: 'generationEnded', jobId: 'j2' },
  { type: 'jobObservedSucceeded', jobId: 'j1' },
  { type: 'jobObservedSucceeded', jobId: 'j2' },
  { type: 'viewJob', jobId: 'j1' },
  { type: 'viewJob', jobId: 'j2' },
  { type: 'submitStarted' },
  { type: 'submitFailed', error: { message: 'x', code: 'UNAVAILABLE' } },
  { type: 'candidateApplied', tripId: 't1' },
  { type: 'openTrip', tripId: 't1' },
  { type: 'openTrip', tripId: 't2' },
  { type: 'openGuide', tripId: 't1' },
  { type: 'openShare', tripId: 't1' },
  { type: 'back' },
  { type: 'restart' },
];

/**
 * Which screen each guarded action requires. Actions not listed here are accepted anywhere. generationStarted is
 * deliberately not guarded: a result that arrives after the user left the condition screen is recorded as the active job.
 */
const REQUIRED_SCREEN: Partial<Record<FlowAction['type'], Screen['name']>> = {
  generationSucceeded: 'progress',
  candidateApplied: 'compare',
  openGuide: 'detail',
  openShare: 'detail',
};

function deepFreeze<T>(value: T): T {
  if (value && typeof value === 'object' && !Object.isFrozen(value)) {
    Object.freeze(value);
    for (const v of Object.values(value)) deepFreeze(v);
  }
  return value;
}

function key(state: FlowState): string {
  return JSON.stringify(state);
}

/** All states reachable within `depth` actions, with one shortest action path to each. */
function reachable(depth: number): { state: FlowState; path: FlowAction[] }[] {
  const seen = new Map<string, { state: FlowState; path: FlowAction[] }>();
  seen.set(key(initialFlow), { state: initialFlow, path: [] });
  let frontier = [{ state: initialFlow, path: [] as FlowAction[] }];
  for (let d = 0; d < depth; d += 1) {
    const next: typeof frontier = [];
    for (const node of frontier) {
      for (const action of ACTIONS) {
        const state = flowReducer(node.state, action);
        const k = key(state);
        if (seen.has(k)) continue;
        const entry = { state, path: [...node.path, action] };
        seen.set(k, entry);
        next.push(entry);
      }
    }
    frontier = next;
  }
  return [...seen.values()];
}

const STATES = reachable(6);
const describePath = (path: FlowAction[]) => path.map(a => a.type).join(' > ') || '(initial)';

describe('flow reducer: exhaustive invariants', () => {
  it('explores a meaningful number of states and reaches every screen kind', () => {
    expect(STATES.length).toBeGreaterThan(40);
    const names = new Set(STATES.map(s => s.state.screen.name));
    for (const n of ['tripList', 'condition', 'progress', 'compare', 'detail', 'guide', 'share', 'feed']) expect(names.has(n as Screen['name'])).toBe(true);
  });

  it('the highlighted tab always matches the screen, after every action from every state', () => {
    for (const { state, path } of STATES) {
      expect(state.tab, `state after ${describePath(path)}`).toBe(tabOf(state.screen));
      for (const action of ACTIONS) {
        const next = flowReducer(state, action);
        expect(next.tab, `${describePath(path)} + ${action.type}`).toBe(tabOf(next.screen));
      }
    }
  });

  it('the history is always a stack that starts at a tab root; an empty history means a tab root', () => {
    const roots = TABS.map(t => TAB_ROOT[t].name);
    for (const { state, path } of STATES) {
      const first = state.history[0];
      if (first) expect(roots, describePath(path)).toContain(first.name);
      else expect(roots, describePath(path)).toContain(state.screen.name);
      // isRoot and canGoBack never disagree about a state that has history.
      if (canGoBack(state)) expect(isRoot(state), describePath(path)).toBe(false);
    }
  });

  it('back from a state without history is a no-op returning the same object', () => {
    for (const { state, path } of STATES) {
      if (state.history.length === 0) expect(flowReducer(state, { type: 'back' }), describePath(path)).toBe(state);
    }
  });

  it('back with history pops exactly one entry and restores that screen', () => {
    for (const { state, path } of STATES) {
      if (state.history.length === 0) continue;
      const next = flowReducer(state, { type: 'back' });
      expect(next.history, describePath(path)).toEqual(state.history.slice(0, -1));
      expect(next.screen, describePath(path)).toEqual(state.history[state.history.length - 1]);
    }
  });

  it('pressing back repeatedly always terminates at a tab root', () => {
    for (const { state, path } of STATES) {
      let s = state;
      for (let i = 0; i < state.history.length; i += 1) s = flowReducer(s, { type: 'back' });
      expect(isRoot(s), describePath(path)).toBe(true);
      expect(flowReducer(s, { type: 'back' })).toBe(s);
    }
  });

  it('selectTab goes to that tab root with an empty history regardless of the current state (新規作成 resumes the active job)', () => {
    for (const { state, path } of STATES) {
      for (const tab of TABS) {
        const next = flowReducer(state, { type: 'selectTab', tab });
        if (tab === 'new' && state.activeJob) {
          // The one exception: 新規作成 resumes the active job (戻る from there goes to the conditions).
          const { jobId, pollAfterMs } = state.activeJob;
          expect(next, describePath(path)).toEqual({ tab, screen: { name: 'progress', jobId, pollAfterMs }, history: [TAB_ROOT.new], activeJob: state.activeJob, otherJobs: state.otherJobs, submitting: state.submitting, submitError: state.submitError });
        } else {
          expect(next, describePath(path)).toEqual({ tab, screen: TAB_ROOT[tab], history: [], activeJob: state.activeJob, otherJobs: state.otherJobs, submitting: state.submitting, submitError: state.submitError });
          expect(isRoot(next)).toBe(true);
        }
      }
    }
  });

  it('restart always lands on a fresh condition screen', () => {
    for (const { state, path } of STATES) {
      expect(flowReducer(state, { type: 'restart' }), describePath(path)).toEqual({ tab: 'new', screen: { name: 'condition' }, history: [], activeJob: null, otherJobs: [], submitting: false, submitError: null });
    }
  });

  it('guarded actions are ignored (same object, no screen jump) unless the required screen is showing', () => {
    for (const { state, path } of STATES) {
      for (const action of ACTIONS) {
        const required = REQUIRED_SCREEN[action.type];
        if (!required) continue;
        const next = flowReducer(state, action);
        if (state.screen.name !== required) expect(next, `${describePath(path)} + ${action.type}`).toBe(state);
        else expect(next, `${describePath(path)} + ${action.type}`).not.toBe(state);
      }
    }
  });

  it('progress is only entered from the condition screen, compare only after progress, so no screen is skipped into', () => {
    for (const { state, path } of STATES) {
      const last = state.history[state.history.length - 1];
      if (state.screen.name === 'progress') expect(last?.name, describePath(path)).toBe('condition');
      if (state.screen.name === 'compare') expect(last?.name, describePath(path)).toBe('condition');
      if (state.screen.name === 'guide' || state.screen.name === 'share') expect(last?.name, describePath(path)).toBe('detail');
    }
  });

  it('a state is never mutated by any action (deep-frozen inputs do not throw)', () => {
    for (const { state, path } of STATES) {
      const frozen = deepFreeze(structuredClone(state));
      for (const action of ACTIONS) {
        expect(() => flowReducer(frozen, action), `${describePath(path)} + ${action.type}`).not.toThrow();
      }
      expect(frozen).toEqual(state);
    }
  });

  it('is deterministic: the same state and action always give an equal result', () => {
    for (const { state } of STATES) {
      for (const action of ACTIONS) expect(flowReducer(state, action)).toEqual(flowReducer(structuredClone(state), structuredClone(action)));
    }
  });
});

describe('flow reducer: active job invariants', () => {
  const unfinishedIds = (state: FlowState) => unfinishedJobs(state).map(j => j.jobId);
  const knownIds = (state: FlowState) => knownJobs(state).map(j => j.jobId);

  it('no unfinished job ever becomes unreachable, except by generationEnded for that job or an explicit restart', () => {
    for (const { state, path } of STATES) {
      for (const action of ACTIONS) {
        if (action.type === 'restart') continue;
        const after = knownIds(flowReducer(state, action));
        for (const id of unfinishedIds(state)) {
          if (action.type === 'generationEnded' && action.jobId === id) continue;
          expect(after, `${describePath(path)} + ${action.type}`).toContain(id);
        }
      }
    }
  });

  it('a job id is known at most once (active and displaced lists never overlap)', () => {
    for (const { state, path } of STATES) {
      const ids = knownIds(state);
      expect(new Set(ids).size, describePath(path)).toBe(ids.length);
    }
  });

  it('a new submission is refused (same object) while a request is in flight or a job is unfinished', () => {
    for (const { state, path } of STATES) {
      const next = flowReducer(state, { type: 'submitStarted' });
      if (state.submitting || unfinishedJobs(state).length > 0) expect(next, describePath(path)).toBe(state);
      else expect(next.submitting, describePath(path)).toBe(true);
    }
  });

  it('only job-related actions change the known jobs', () => {
    const changing = new Set<FlowAction['type']>(['generationStarted', 'generationEnded', 'generationSucceeded', 'jobObservedSucceeded', 'viewJob', 'candidateApplied', 'restart']);
    for (const { state, path } of STATES) {
      for (const action of ACTIONS) {
        if (changing.has(action.type)) continue;
        const after = flowReducer(state, action);
        expect(after.activeJob, `${describePath(path)} + ${action.type}`).toEqual(state.activeJob);
        expect(after.otherJobs, `${describePath(path)} + ${action.type}`).toEqual(state.otherJobs);
      }
    }
  });

  it('the job ids are never invented: they are always ones that were started', () => {
    for (const { state, path } of STATES) {
      for (const id of knownIds(state)) expect(['j1', 'j2'], describePath(path)).toContain(id);
    }
  });
});

describe('flow reducer: stale and late actions', () => {
  const start = (actions: FlowAction[]) => actions.reduce(flowReducer, initialFlow);
  const toProgress = (jobId = 'j1') => start([{ type: 'selectTab', tab: 'new' }, { type: 'generationStarted', jobId, pollAfterMs: 700 }]);

  it('a generation result that arrives after leaving progress (back, tab switch, restart) does not move the user', () => {
    const afterBack = flowReducer(toProgress(), { type: 'back' });
    const afterTab = flowReducer(toProgress(), { type: 'selectTab', tab: 'feed' });
    const afterRestart = flowReducer(toProgress(), { type: 'restart' });
    for (const s of [afterBack, afterTab, afterRestart]) {
      expect(flowReducer(s, { type: 'generationSucceeded', batchId: 'late' })).toBe(s);
    }
  });

  it('a second job accepted while one is shown (e.g. a double submit) replaces the screen but keeps the first job reachable', () => {
    const first = toProgress('j1');
    const second = flowReducer(first, { type: 'generationStarted', jobId: 'j2', pollAfterMs: 700 });
    expect(second.screen).toMatchObject({ name: 'progress', jobId: 'j2' });
    expect(second.otherJobs.map(j => j.jobId)).toEqual(['j1']);
    expect(second.history).toHaveLength(1);
  });

  it('a second candidateApplied (double tap on 採用) opens the trip once', () => {
    const compare = flowReducer(toProgress(), { type: 'generationSucceeded', batchId: 'b1' });
    const applied = flowReducer(compare, { type: 'candidateApplied', tripId: 't1' });
    expect(applied.screen).toEqual({ name: 'detail', tripId: 't1' });
    expect(flowReducer(applied, { type: 'candidateApplied', tripId: 't2' })).toBe(applied);
  });

  it('an apply result that arrives after the user went back to the conditions is ignored', () => {
    const compare = flowReducer(toProgress(), { type: 'generationSucceeded', batchId: 'b1' });
    const back = flowReducer(compare, { type: 'back' });
    expect(back.screen).toEqual({ name: 'condition' });
    expect(flowReducer(back, { type: 'candidateApplied', tripId: 't1' })).toBe(back);
  });

  it('after a successful apply, 戻る goes to the trip list, then stops (no way back into the finished flow)', () => {
    const compare = flowReducer(toProgress(), { type: 'generationSucceeded', batchId: 'b1' });
    const applied = flowReducer(compare, { type: 'candidateApplied', tripId: 't1' });
    const list = flowReducer(applied, { type: 'back' });
    expect(list).toEqual(initialFlow);
    expect(flowReducer(list, { type: 'back' })).toBe(list);
  });

  it('openGuide/openShare keep the trip id they were given (no cross-trip leakage through history)', () => {
    const detail = start([{ type: 'openTrip', tripId: 't1' }]);
    const guide = flowReducer(detail, { type: 'openGuide', tripId: 't1' });
    expect(guide.screen).toEqual({ name: 'guide', tripId: 't1' });
    expect(guide.history.map(h => (h.name === 'detail' ? h.tripId : null))).toEqual([null, 't1']);
  });

  /**
   * R28 / U05: leaving the progress screen (tab, 戻る) must not cancel or forget the job. The flow state keeps the
   * active job reachable; only an explicit restart, an adopted candidate, a new generation, or a failed/cancelled
   * job observed by the progress screen clears it.
   */
  it('leaving the progress screen by tab or 戻る keeps the active job reachable, and 新規作成 resumes it', () => {
    for (const action of [{ type: 'selectTab', tab: 'feed' }, { type: 'selectTab', tab: 'trips' }, { type: 'back' }] as const) {
      const left = flowReducer(toProgress('job_running'), action);
      expect(left.screen.name, action.type).not.toBe('progress');
      expect(left.activeJob, action.type).toEqual({ jobId: 'job_running', pollAfterMs: 700, succeeded: false });
      expect(flowReducer(left, { type: 'selectTab', tab: 'new' }).screen, action.type).toEqual({ name: 'progress', jobId: 'job_running', pollAfterMs: 700 });
    }
  });

  it('restart explicitly forgets the active job', () => {
    const left = flowReducer(toProgress('job_running'), { type: 'restart' });
    expect(left.activeJob).toBeNull();
    expect(JSON.stringify(left)).not.toContain('job_running');
  });
});
